#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include "buildscript.h"
#include "cartxml.h"
#include "driver.h"
#include "pathutil.h"

#define MARKER "Generated by v32c++"

static int is_absolute(const char *p) {
    return p[0] == '/' || p[0] == '\\' || (p[0] != '\0' && p[1] == ':');
}

static char *join_path(const char *dir, const char *name) {
    if (is_absolute(name) || strcmp(dir, ".") == 0) return strdup(name);
    size_t cap = strlen(dir) + strlen(name) + 2;
    char *r = malloc(cap);
    snprintf(r, cap, "%s/%s", dir, name);
    return r;
}

static int dir_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0 && (st.st_mode & S_IFDIR) != 0;
}

char *build_script_dir(const char *output_filename, const char *source_filename) {
    char *src_dir = path_dirname(source_filename);
    char *parent = join_path(src_dir, "..");
    char *out_dir = path_dirname(output_filename);
    char *name_rel = path_relative_to(parent, src_dir);
    char *out_rel = path_relative_to(parent, out_dir);
    char *obj_dir = join_path(parent, "obj");
    int use_parent = strcmp(name_rel, "src") == 0 &&
                     (strcmp(out_rel, "obj") == 0 || dir_exists(obj_dir));
    char *result = use_parent ? parent : src_dir;
    if (use_parent) free(src_dir); else free(parent);
    free(out_dir); free(name_rel); free(out_rel); free(obj_dir);
    return result;
}

/* ---- small helpers ---------------------------------------------------- */

typedef struct { char **items; int count; } StrSet;

static void set_add(StrSet *s, const char *v) {
    for (int i = 0; i < s->count; i++)
        if (strcmp(s->items[i], v) == 0) return;
    s->items = realloc(s->items, (size_t)(s->count + 1) * sizeof *s->items);
    s->items[s->count++] = strdup(v);
}

static void set_free(StrSet *s) {
    for (int i = 0; i < s->count; i++) free(s->items[i]);
    free(s->items);
}

/* One conversion: tool, input, output (all relative to the script dir). */
typedef struct { char *in; char *out; } Asset;

typedef struct {
    char  *script_dir;
    char  *src, *c, *asm_, *vbin, *asm_opt, *vbin_opt;
    char  *xml, *xml_opt, *rom, *rom_opt;
    char  *obj_dir;            /* directory of the .c, relative; "." possible */
    Asset *tex; int ntex;
    Asset *snd; int nsnd;
    StrSet dirs;               /* directories the script must create */
    char **args; int *is_path; int nargs;
} Plan;

static char *rel(const char *script_dir, const char *path) {
    return path_relative_to(script_dir, path);
}

static char *with_ext(const char *path, const char *ext) {
    return replace_extension(path, ext);
}

static void add_dir_of(Plan *pl, const char *file) {
    char *d = path_dirname(file);
    if (strcmp(d, ".") != 0) set_add(&pl->dirs, d);
    free(d);
}

static void collect_assets(Plan *pl, const CartResourceList *list, const char *tag,
                           const char *ext, int preserve, const char *src_dir,
                           const char *out_dir, Asset **assets, int *count) {
    if (list->count == 0) return;
    char **names = cart_resource_names(list, tag, ext, preserve);
    *assets = calloc((size_t)list->count, sizeof **assets);
    for (int i = 0; i < list->count; i++) {
        const char *hint = list->items[i].filename;
        char *in_full  = preserve ? join_path(src_dir, hint) : strdup(hint);
        char *out_full = join_path(preserve ? src_dir : out_dir, names[i]);
        char *in_rel = rel(pl->script_dir, in_full);
        char *out_rel = rel(pl->script_dir, out_full);
        int dup = 0;
        for (int j = 0; j < *count; j++)
            if (strcmp((*assets)[j].out, out_rel) == 0) dup = 1;
        if (dup) { free(in_rel); free(out_rel); }
        else {
            (*assets)[*count].in = in_rel;
            (*assets)[*count].out = out_rel;
            (*count)++;
            add_dir_of(pl, out_rel);
        }
        free(in_full); free(out_full); free(names[i]);
    }
    free(names);
}

static void to_backslashes(char *s) {
    for (; *s; s++) if (*s == '/') *s = '\\';
}

/* ---- quoting ---------------------------------------------------------- */

static void put_sh(FILE *f, const char *s) {
    int plain = (*s != '\0');
    for (const char *p = s; *p; p++)
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || strchr("_./=:,+-", *p))) plain = 0;
    if (plain) { fputs(s, f); return; }
    fputc('\'', f);
    for (const char *p = s; *p; p++) {
        if (*p == '\'') fputs("'\\''", f); else fputc(*p, f);
    }
    fputc('\'', f);
}

static void put_bat(FILE *f, const char *s) {
    int plain = (*s != '\0');
    for (const char *p = s; *p; p++)
        if (strchr(" \t&|<>^%\"()!,;=", *p)) plain = 0;
    if (plain) { fputs(s, f); return; }
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        if (*p == '%') fputs("%%", f);
        else if (*p == '"') fputs("\\\"", f);
        else fputc(*p, f);
    }
    fputc('"', f);
}

/* ---- Make.sh ---------------------------------------------------------- */

static void sh_section(FILE *f, const char *title) {
    fprintf(f, "\necho\necho %s\necho --------------------------\n", title);
}

static void write_sh(FILE *f, const Plan *pl) {
    fputs("#!/bin/bash\n", f);
    fputs("# " MARKER " from the source's own cart hints and command line. Edit\n"
          "# the source (or use --no-build-scripts and keep a hand-written script)\n"
          "# rather than this file: it is rewritten on every v32c++ run.\n\n", f);
    fputs("abort_build()\n{\n    echo\n    echo BUILD FAILED\n    exit 1\n}\n\n", f);
    fputs("# the tools this build needs\n"
          "need_tool()\n{\n"
          "    command -v \"$1\" >/dev/null 2>&1 || { echo \"ERROR: $1 is needed to build, but was not found in PATH\"; abort_build; }\n}\n\n", f);
    fputs("need_tool v32c++\nneed_tool compile\nneed_tool assemble\nneed_tool packrom\n", f);
    if (pl->ntex) fputs("need_tool png2vircon\n", f);
    if (pl->nsnd) fputs("need_tool wav2vircon\n", f);
    fputs("\n# the optimizer is optional: without it only the regular build is made\n"
          "HAVE_OPT=0\n"
          "if command -v v32opt >/dev/null 2>&1; then\n    HAVE_OPT=1\nelse\n"
          "    echo \"note: v32opt not found in PATH -- skipping the optimized (Opt) build\"\nfi\n", f);
    fputs("\n# create the output folders, since the development tools will not\n", f);
    fputs("mkdir -p bin\n", f);
    for (int i = 0; i < pl->dirs.count; i++) {
        fputs("mkdir -p ", f); put_sh(f, pl->dirs.items[i]); fputc('\n', f);
    }

    sh_section(f, "Transpile to Vircon32 C");
    fputs("v32c++", f);
    for (int i = 0; i < pl->nargs; i++) { fputc(' ', f); put_sh(f, pl->args[i]); }
    fputs(" --no-build-scripts -o ", f); put_sh(f, pl->c);
    fputc(' ', f); put_sh(f, pl->src); fputs(" || abort_build\n", f);

    sh_section(f, "Compile the C code");
    fputs("compile ", f); put_sh(f, pl->c); fputs(" -o ", f); put_sh(f, pl->asm_);
    fputs(" || abort_build\n", f);
    fputs("if [ \"$HAVE_OPT\" = 1 ]; then\n    v32opt -O3 ", f); put_sh(f, pl->asm_);
    fputs(" -o ", f); put_sh(f, pl->asm_opt); fputs(" || abort_build\nfi\n", f);

    sh_section(f, "Assemble the ASM code");
    fputs("assemble ", f); put_sh(f, pl->asm_); fputs(" -o ", f); put_sh(f, pl->vbin);
    fputs(" || abort_build\n", f);
    fputs("if [ \"$HAVE_OPT\" = 1 ]; then\n    assemble ", f); put_sh(f, pl->asm_opt);
    fputs(" -o ", f); put_sh(f, pl->vbin_opt); fputs(" || abort_build\nfi\n", f);

    if (pl->ntex) {
        sh_section(f, "Convert the PNG textures");
        for (int i = 0; i < pl->ntex; i++) {
            fputs("png2vircon ", f); put_sh(f, pl->tex[i].in); fputs(" -o ", f);
            put_sh(f, pl->tex[i].out); fputs(" || abort_build\n", f);
        }
    }
    if (pl->nsnd) {
        sh_section(f, "Convert the WAV sounds");
        for (int i = 0; i < pl->nsnd; i++) {
            fputs("wav2vircon ", f); put_sh(f, pl->snd[i].in); fputs(" -o ", f);
            put_sh(f, pl->snd[i].out); fputs(" || abort_build\n", f);
        }
    }

    sh_section(f, "Pack the ROM");
    fputs("packrom ", f); put_sh(f, pl->xml); fputs(" -o ", f); put_sh(f, pl->rom);
    fputs(" || abort_build\n", f);
    fputs("if [ \"$HAVE_OPT\" = 1 ]; then\n    packrom ", f); put_sh(f, pl->xml_opt);
    fputs(" -o ", f); put_sh(f, pl->rom_opt); fputs(" || abort_build\nfi\n", f);

    fputs("\necho\necho BUILD SUCCESSFUL\n", f);
}

/* ---- Make.bat --------------------------------------------------------- */

/* Writes `s` with its '/' turned into '\' (for paths), quoted if needed. */
static void put_bat_path(FILE *f, const char *s) {
    char *c = strdup(s);
    to_backslashes(c);
    put_bat(f, c);
    free(c);
}

static void bat_section(FILE *f, const char *title) {
    fprintf(f, "\r\necho.\r\necho %s\r\necho --------------------------\r\n", title);
}

static void write_bat(FILE *f, const Plan *pl) {
    fputs("@echo off\r\n", f);
    fputs("REM " MARKER " from the source's own cart hints and command line. Edit\r\n"
          "REM the source (or use --no-build-scripts and keep a hand-written script)\r\n"
          "REM rather than this file: it is rewritten on every v32c++ run.\r\n\r\n", f);
    fputs("REM the tools this build needs\r\n", f);
    const char *needed[] = { "v32c++", "compile", "assemble", "packrom", "png2vircon", "wav2vircon" };
    for (int i = 0; i < 6; i++) {
        if (i == 4 && !pl->ntex) continue;
        if (i == 5 && !pl->nsnd) continue;
        fprintf(f, "where %s >nul 2>nul\r\nif errorlevel 1 (\r\n"
                   "    echo ERROR: %s is needed to build, but was not found in PATH\r\n"
                   "    goto :failed\r\n)\r\n", needed[i], needed[i]);
    }
    fputs("\r\nREM the optimizer is optional: without it only the regular build is made\r\n"
          "set HAVE_OPT=0\r\n"
          "where v32opt >nul 2>nul\r\nif not errorlevel 1 set HAVE_OPT=1\r\n"
          "if \"%HAVE_OPT%\"==\"0\" echo note: v32opt not found in PATH -- skipping the optimized Opt build\r\n", f);
    fputs("\r\nREM create the output folders, since the development tools will not\r\n"
          "if not exist bin mkdir bin\r\n", f);
    for (int i = 0; i < pl->dirs.count; i++) {
        fputs("if not exist ", f); put_bat_path(f, pl->dirs.items[i]);
        fputs(" mkdir ", f); put_bat_path(f, pl->dirs.items[i]); fputs("\r\n", f);
    }

    bat_section(f, "Transpile to Vircon32 C");
    fputs("v32c++", f);
    for (int i = 0; i < pl->nargs; i++) {
        fputc(' ', f);
        if (pl->is_path[i]) put_bat_path(f, pl->args[i]); else put_bat(f, pl->args[i]);
    }
    fputs(" --no-build-scripts -o ", f); put_bat_path(f, pl->c);
    fputc(' ', f); put_bat_path(f, pl->src); fputs(" || goto :failed\r\n", f);

    bat_section(f, "Compile the C code");
    fputs("compile ", f); put_bat_path(f, pl->c); fputs(" -o ", f); put_bat_path(f, pl->asm_);
    fputs(" || goto :failed\r\n", f);
    fputs("if \"%HAVE_OPT%\"==\"1\" v32opt -O3 ", f); put_bat_path(f, pl->asm_);
    fputs(" -o ", f); put_bat_path(f, pl->asm_opt); fputs(" || goto :failed\r\n", f);

    bat_section(f, "Assemble the ASM code");
    fputs("assemble ", f); put_bat_path(f, pl->asm_); fputs(" -o ", f); put_bat_path(f, pl->vbin);
    fputs(" || goto :failed\r\n", f);
    fputs("if \"%HAVE_OPT%\"==\"1\" assemble ", f); put_bat_path(f, pl->asm_opt);
    fputs(" -o ", f); put_bat_path(f, pl->vbin_opt); fputs(" || goto :failed\r\n", f);

    if (pl->ntex) {
        bat_section(f, "Convert the PNG textures");
        for (int i = 0; i < pl->ntex; i++) {
            fputs("png2vircon ", f); put_bat_path(f, pl->tex[i].in); fputs(" -o ", f);
            put_bat_path(f, pl->tex[i].out); fputs(" || goto :failed\r\n", f);
        }
    }
    if (pl->nsnd) {
        bat_section(f, "Convert the WAV sounds");
        for (int i = 0; i < pl->nsnd; i++) {
            fputs("wav2vircon ", f); put_bat_path(f, pl->snd[i].in); fputs(" -o ", f);
            put_bat_path(f, pl->snd[i].out); fputs(" || goto :failed\r\n", f);
        }
    }

    bat_section(f, "Pack the ROM");
    fputs("packrom ", f); put_bat_path(f, pl->xml); fputs(" -o ", f); put_bat_path(f, pl->rom);
    fputs(" || goto :failed\r\n", f);
    fputs("if \"%HAVE_OPT%\"==\"1\" packrom ", f); put_bat_path(f, pl->xml_opt);
    fputs(" -o ", f); put_bat_path(f, pl->rom_opt); fputs(" || goto :failed\r\n", f);
    fputs("goto :succeeded\r\n\r\n:failed\r\necho.\r\necho BUILD FAILED\r\nexit /b 1\r\n\r\n"
          ":succeeded\r\necho.\r\necho BUILD SUCCESSFUL\r\nexit /b 0\r\n", f);
}

/* ---- driver ----------------------------------------------------------- */

/* A file that exists but wasn't written by v32c++ is somebody's own script. */
static int is_foreign_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (f == NULL) return 0;
    char buf[512];
    size_t n = fread(buf, 1, sizeof buf - 1, f);
    fclose(f);
    buf[n] = '\0';
    return strstr(buf, MARKER) == NULL;
}

static void write_script(const char *dir, const char *name, int bat, const Plan *pl) {
    char *path = join_path(dir, name);
    if (is_foreign_file(path)) {
        fprintf(stderr, "---- warning: %s exists and was not generated by v32c++; "
                        "leaving it alone (--no-build-scripts silences this) ----\n", path);
        free(path);
        return;
    }
    FILE *f = fopen(path, "wb");
    if (f == NULL) { perror(path); free(path); return; }
    if (bat) write_bat(f, pl); else write_sh(f, pl);
    fclose(f);
#ifndef _WIN32
    if (!bat) chmod(path, 0755);
#endif
    free(path);
}

void emit_build_scripts(const char *output_filename, const char *source_filename,
                        int is_bios, int preserve_paths,
                        const char *const *args, const int *arg_is_path,
                        int arg_count) {
    (void)is_bios;   /* -b arrives through `args`; the pack step is the same */
    Plan pl;
    memset(&pl, 0, sizeof pl);
    pl.script_dir = build_script_dir(output_filename, source_filename);
    char *src_dir = path_dirname(source_filename);
    char *out_dir = path_dirname(output_filename);

    pl.src      = rel(pl.script_dir, source_filename);
    pl.c        = rel(pl.script_dir, output_filename);
    pl.asm_     = with_ext(pl.c, ".asm");
    pl.vbin     = with_ext(pl.c, ".vbin");
    pl.asm_opt  = with_ext(pl.c, "Opt.asm");
    pl.vbin_opt = with_ext(pl.c, "Opt.vbin");

    char *xml_abs = cart_xml_filename(output_filename, source_filename, preserve_paths);
    pl.xml = rel(pl.script_dir, xml_abs);
    pl.xml_opt = with_ext(pl.xml, "Opt.xml");
    free(xml_abs);

    char *base = with_ext(path_basename(pl.c), "");
    size_t cap = strlen(base) + 16;
    pl.rom = malloc(cap);     snprintf(pl.rom, cap, "bin/%s.v32", base);
    pl.rom_opt = malloc(cap); snprintf(pl.rom_opt, cap, "bin/%sOpt.v32", base);
    free(base);

    add_dir_of(&pl, pl.c);   /* obj/ first, then any asset subdirectories */
    collect_assets(&pl, &g_cart_textures, "texture", ".vtex", preserve_paths,
                   src_dir, out_dir, &pl.tex, &pl.ntex);
    collect_assets(&pl, &g_cart_sounds, "sound", ".vsnd", preserve_paths,
                   src_dir, out_dir, &pl.snd, &pl.nsnd);

    pl.nargs = arg_count;
    pl.args = calloc((size_t)arg_count + 1, sizeof *pl.args);
    pl.is_path = calloc((size_t)arg_count + 1, sizeof *pl.is_path);
    for (int i = 0; i < arg_count; i++) {
        pl.is_path[i] = arg_is_path[i];
        pl.args[i] = arg_is_path[i] ? rel(pl.script_dir, args[i]) : strdup(args[i]);
    }

    write_script(pl.script_dir, "Make.sh", 0, &pl);
    write_script(pl.script_dir, "Make.bat", 1, &pl);

    for (int i = 0; i < pl.nargs; i++) free(pl.args[i]);
    free(pl.args); free(pl.is_path);
    for (int i = 0; i < pl.ntex; i++) { free(pl.tex[i].in); free(pl.tex[i].out); }
    for (int i = 0; i < pl.nsnd; i++) { free(pl.snd[i].in); free(pl.snd[i].out); }
    free(pl.tex); free(pl.snd);
    set_free(&pl.dirs);
    free(pl.script_dir); free(pl.src); free(pl.c); free(pl.asm_); free(pl.vbin);
    free(pl.asm_opt); free(pl.vbin_opt); free(pl.xml); free(pl.xml_opt);
    free(pl.rom); free(pl.rom_opt); free(src_dir); free(out_dir);
}
